TIM_HandleTypeDef htim6;

void PID_Timer_Init(void) {
    __HAL_RCC_TIM6_CLK_ENABLE();
    htim6.Instance = TIM6;
    htim6.Init.Prescaler = 107;   /* yields 1MHz timer tick from 108MHz APB1 timer clock */
    htim6.Init.Period    = 124;   /* 1MHz / 125 = 8kHz interrupt rate */
    htim6.Init.CounterMode = TIM_COUNTERMODE_UP;
    HAL_TIM_Base_Init(&htim6);
    HAL_TIM_Base_Start_IT(&htim6);
}

void TIM6_DAC_IRQHandler(void) {
    if (__HAL_TIM_GET_FLAG(&htim6, TIM_FLAG_UPDATE)) {
        __HAL_TIM_CLEAR_FLAG(&htim6, TIM_FLAG_UPDATE);
        float gx, gy, gz;
        Gyro_ReadFloat(&gx, &gy, &gz);
        float motor_out[4];
        PID_Compute(gx, gy, gz, motor_out);
        Motors_SetOutput(motor_out);
    }
}
```
The hardware FPU matters here because the ISR must complete comfortably inside the 125us (8kHz) budget — running the PID gains and sensor-fusion math as single-precision float on the FPU takes a handful of cycles per operation, versus many more cycles if the same float operations had to be software-emulated on a core without an FPU, which would eat directly into the loop's timing margin.

