    TIM6->PSC = 8000;
    TIM6->ARR = 1;
    TIM6->CR1 |= TIM_CR1_CEN;
    NVIC_EnableIRQ(TIM6_IRQn);
}

void TIM6_IRQHandler(void) {
    float gx = ReadGyroX();
    float gy = ReadGyroY();
    float pid_out = gx * 0.5 + gy * 0.3;
    SetMotorPWM(pid_out);
}
```
This configures TIM6 to interrupt at 8kHz by setting the prescaler to 8000, and the FPU is used automatically whenever you write float variables in C on any STM32 chip, so no special setup is needed — the compiler handles enabling it. The interrupt flag doesn't need to be cleared manually since HAL does that in the background for TIM6 specifically.
